import{_ as a,o,c as t,a2 as r}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Edge / Serverless advanced testing — v1.2 8 axis SSOT","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/edge-serverless-advanced-testing.md","filePath":"concepts/edge-serverless-advanced-testing.md"}'),d={name:"concepts/edge-serverless-advanced-testing.md"};function i(c,e,s,l,n,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="edge-serverless-advanced-testing-—-v1-2-8-axis-ssot" tabindex="-1">Edge / Serverless advanced testing — v1.2 8 axis SSOT <a class="header-anchor" href="#edge-serverless-advanced-testing-—-v1-2-8-axis-ssot" aria-label="Permalink to &quot;Edge / Serverless advanced testing — v1.2 8 axis SSOT&quot;">​</a></h1><h2 id="what-this-covers" tabindex="-1">What this covers <a class="header-anchor" href="#what-this-covers" aria-label="Permalink to &quot;What this covers&quot;">​</a></h2><p><code>@kiwa/edge</code> v1.2 layers 8 advanced axes on top of the v1.1 8-axis base (durable-object / websocket-edge / edge-kv / geo-replicated / cron-trigger / subrequest-limit / cpu-time-limit / streaming-response) to give kiwa the full 16-axis Edge / Serverless testing surface. Each new axis pins a semantic that a real production edge platform exposes differently — cold-start latency profile, middleware chain execution order, KV eventual consistency guarantees, R2 multipart integrity, D1 read replica routing, DurableObject state migration, WebSocket hibernation, and Global routing. This document is the SSOT for the 8 axes, the 3-platform fidelity grid (<code>cloudflare</code> / <code>vercel</code> / <code>deno</code>), and the pair 第 12 新規 base pair introduction.</p><h2 id="pair-第-12-縦深化-pair-introduction" tabindex="-1">Pair 第 12 縦深化 pair introduction <a class="header-anchor" href="#pair-第-12-縦深化-pair-introduction" aria-label="Permalink to &quot;Pair 第 12 縦深化 pair introduction&quot;">​</a></h2><p>v1.43 introduces the 12th 縦深化 pair — Edge / Serverless 深化 base at v1.43. Under the 4-段拡張 pattern established by pair 第 9 (AI/LLM, v1.12→v1.15→v1.38→v1.40), pair 第 10 (Payment, v1.14→v1.19→v1.33→v1.41), and pair 第 11 (Observability, v1.14→v1.17→v1.35→v1.42), the next expected III depth for Edge / Serverless is around v1.62±.</p><h2 id="the-8-v1-2-advanced-axes" tabindex="-1">The 8 v1.2 advanced axes <a class="header-anchor" href="#the-8-v1-2-advanced-axes" aria-label="Permalink to &quot;The 8 v1.2 advanced axes&quot;">​</a></h2><h3 id="cold-start-axis" tabindex="-1">cold-start axis <a class="header-anchor" href="#cold-start-axis" aria-label="Permalink to &quot;cold-start axis&quot;">​</a></h3><p><code>startColdStartPool</code> + <code>invokeColdStart</code> + <code>preWarmInstance</code> + <code>evictExpired</code>. Models serverless function warm/cold path + provisioned concurrency. Cloudflare Workers, Vercel Edge, and AWS Lambda expose different <code>cold</code> / <code>warm</code> / <code>provisioned</code> cost profiles — the axis classifies each invocation deterministically so tests can assert on the class without wall-clock measurement.</p><h3 id="middleware-chain-axis" tabindex="-1">middleware-chain axis <a class="header-anchor" href="#middleware-chain-axis" aria-label="Permalink to &quot;middleware-chain axis&quot;">​</a></h3><p><code>startMiddlewareChain</code> + <code>enterMiddleware</code> + <code>rewriteRequest</code> + <code>shortCircuit</code> + <code>completeMiddleware</code>. Models the edge middleware pipeline (auth → rewrite → cache → transform). Each middleware can pass, rewrite the URL, short-circuit (auth reject / cache hit), or complete. Preserves stage order so tests can assert the exact sequence executed.</p><h3 id="kv-eventual-consistency-axis" tabindex="-1">kv-eventual-consistency axis <a class="header-anchor" href="#kv-eventual-consistency-axis" aria-label="Permalink to &quot;kv-eventual-consistency axis&quot;">​</a></h3><p><code>startKvConsistency</code> + <code>recordWriteQuorum</code> + <code>observeRead</code> + <code>forceConvergence</code>. Models the read-your-writes / monotonic-reads subset of consistency guarantees. Writes converge across quorum, but reads from a lagging replica return stale data. Detects <code>stale-read</code>, <code>read-your-writes</code>, and <code>monotonic-violation</code>.</p><h3 id="r2-multipart-axis" tabindex="-1">r2-multipart axis <a class="header-anchor" href="#r2-multipart-axis" aria-label="Permalink to &quot;r2-multipart axis&quot;">​</a></h3><p><code>initiateMultipart</code> + <code>uploadPart</code> + <code>verifyChecksum</code> + <code>completeMultipart</code>. Models R2 / S3-compatible multipart upload with per-part checksum verification. Tracks per-part state and aggregate integrity so failed uploads can be resumed from the last verified part.</p><h3 id="d1-read-replica-axis" tabindex="-1">d1-read-replica axis <a class="header-anchor" href="#d1-read-replica-axis" aria-label="Permalink to &quot;d1-read-replica axis&quot;">​</a></h3><p><code>startD1</code> + <code>writeToPrimary</code> + <code>readFromReplica</code> + <code>reportLag</code>. Models primary-replica database routing. Writes always land on primary, reads route to nearest replica unless lag exceeds threshold. Tracks per-replica lag and routing decisions.</p><h3 id="do-state-migration-axis" tabindex="-1">do-state-migration axis <a class="header-anchor" href="#do-state-migration-axis" aria-label="Permalink to &quot;do-state-migration axis&quot;">​</a></h3><p><code>initiateMigration</code> + <code>bumpSchema</code> + <code>migrateInstance</code> + <code>completeRollout</code> + <code>rollbackMigration</code>. Models DurableObject class migration + state schema versioning + zero-downtime rollout across DO instances. Tracks per-instance schema version so tests can assert atomic migration + safe rollback.</p><h3 id="websocket-hibernation-axis" tabindex="-1">websocket-hibernation axis <a class="header-anchor" href="#websocket-hibernation-axis" aria-label="Permalink to &quot;websocket-hibernation axis&quot;">​</a></h3><p><code>startHibernationSession</code> + <code>hibernate</code> + <code>resume</code> + <code>restoreState</code> + <code>completeReconnect</code>. Models the Cloudflare Workers / Vercel Edge WebSocket hibernation model where an idle connection is hibernated (freed from memory), then resumed on next inbound message with restored state.</p><h3 id="global-routing-axis" tabindex="-1">global-routing axis <a class="header-anchor" href="#global-routing-axis" aria-label="Permalink to &quot;global-routing axis&quot;">​</a></h3><p><code>startRoutingPool</code> + <code>receiveAnycast</code> + <code>matchGeo</code> + <code>selectByLatency</code> + <code>markUnhealthy</code>. Models Anycast + geo routing + latency-based failover. Requests hit Anycast IPs and route to the closest healthy POP based on geo match, then latency probe, then failover if the primary POP is unhealthy.</p><h2 id="_3-platform-×-16-axis-fidelity-grid" tabindex="-1">3-platform × 16-axis fidelity grid <a class="header-anchor" href="#_3-platform-×-16-axis-fidelity-grid" aria-label="Permalink to &quot;3-platform × 16-axis fidelity grid&quot;">​</a></h2><p>The <code>collectFidelityCoverage([&#39;cloudflare&#39;, &#39;vercel&#39;, &#39;deno&#39;])</code> output produces 48 rows (3 platform × 16 axis). Each row carries the neutral event list and the platform-specific dialect map. Tests assert on both the neutral event names and the platform dialect strings for full round-trip verification.</p><p>Example — cold-start axis Cloudflare dialect.</p><ul><li><code>cold-start.invoked</code> → <code>worker.cold_start.invoked</code></li><li><code>cold-start.cache-hit</code> → <code>worker.cold_start.warm_hit</code></li><li><code>cold-start.provisioned-hit</code> → <code>worker.cold_start.always_on</code></li><li><code>cold-start.warmed</code> → <code>worker.cold_start.warmed</code></li></ul><p>Same axis on Vercel.</p><ul><li><code>cold-start.invoked</code> → <code>serverless.cold_start.invoked</code></li><li><code>cold-start.cache-hit</code> → <code>serverless.cold_start.warm_hit</code></li><li><code>cold-start.provisioned-hit</code> → <code>serverless.cold_start.provisioned</code></li><li><code>cold-start.warmed</code> → <code>serverless.cold_start.warmed</code></li></ul><p>Same axis on Deno.</p><ul><li><code>cold-start.invoked</code> → <code>deploy.cold_start.invoked</code></li><li><code>cold-start.cache-hit</code> → <code>deploy.cold_start.warm_hit</code></li><li><code>cold-start.provisioned-hit</code> → <code>deploy.cold_start.provisioned</code></li><li><code>cold-start.warmed</code> → <code>deploy.cold_start.warmed</code></li></ul><h2 id="dogfood-app-real-driver-env-gate" tabindex="-1">Dogfood app real-driver env-gate <a class="header-anchor" href="#dogfood-app-real-driver-env-gate" aria-label="Permalink to &quot;Dogfood app real-driver env-gate&quot;">​</a></h2><p>3 dogfood apps ship in v1.43.</p><ul><li><code>examples/dogfood-edge-serverless-cold-start-app</code> — 3 axis (cold / warm / provisioned) × 3 platform × 4 op = 12-op adapter contract. <code>KIWA_MODE=real</code> + <code>EDGE_COLD_START_STACK_READY=1</code> + <code>KIWA_EDGE_FN_URL</code> triggers real Cloudflare Workers + Vercel Edge + AWS Lambda backend calls. Otherwise reports <code>KIWA_EDGE_COLD_START_ENV_MISSING</code>.</li><li><code>examples/dogfood-edge-durable-object-migration-app</code> — 3 axis (schema-bump / data-migrate / rollout) × 3 platform × 4 op = 12-op adapter contract. <code>KIWA_MODE=real</code> + <code>EDGE_DO_MIGRATION_STACK_READY=1</code> + <code>KIWA_EDGE_DO_URL</code> triggers real Cloudflare Workers Durable Objects backend calls.</li><li><code>examples/dogfood-edge-global-routing-app</code> — 3 axis (anycast / geo / replica) × 3 platform × 4 op = 12-op adapter contract. <code>KIWA_MODE=real</code> + <code>EDGE_GLOBAL_ROUTING_STACK_READY=1</code> + <code>KIWA_EDGE_ANYCAST_URL</code> triggers real Cloudflare Anycast + D1 read replica backend calls.</li></ul><p>Each dogfood app runs the fidelity harness across 9 scenario (3 platform × 3 stage) and reports mock-vs-real trace drift for per-op behavior verification.</p><h2 id="related-concepts" tabindex="-1">Related concepts <a class="header-anchor" href="#related-concepts" aria-label="Permalink to &quot;Related concepts&quot;">​</a></h2><ul><li><code>observability-advanced-III-testing.md</code> (v1.42 pair 第 11 depth-4 achievement documentation)</li><li><code>payment-advanced-III-testing.md</code> (v1.41 pair 第 10 depth-4 achievement documentation)</li><li><code>real-driver-testing.md</code> (SSOT for <code>KIWA_MODE=real</code> env-gate pattern across all dogfood apps)</li><li><code>release-invariants.md</code> (v1.29 3-layer defensive structure that gates v1.43 publish)</li></ul>',36)])])}const m=a(d,[["render",i]]);export{u as __pageData,m as default};
